L["Enables sharpening to improve image clarity. Especially noticeable at lower render scales."] = "Включает резкость для улучшения четкости изображения. Особенно заметно при низком масштабе рендеринга."
L["Havoc"] = "Истребление"
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "Скрывает кнопку EllesmereUI из главного меню паузы игры (клавиша Esc)."
L["Hides the sync icons on the sidebar module list."] = "Скрывает иконки синхронизации в списке модулей боковой панели."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "Скрывает кнопку режима разблокировки из меню паузы игры. Вы все еще можете включить его из настроек EUI."
L["Import the anchor & size-match relationships from this profile. Off = keep your own layout; only the selected modules' own positions/settings come in."] = "Импортировать связи привязки и сопоставления размеров из этого профиля. Выкл = сохранить собственную разметку; импортируются только настройки и положения выбранных модулей."
L["In Maintenance"] = "На техническом обслуживании"
L["Include the anchor & size-match relationships between modules. Off = export each module's own positions only, with no cross-module tying."] = "Включить связи привязки и сопоставления размеров между модулями. Выкл = экспортировать только положения каждого отдельного модуля без межмодульных связей."
L["Keybinds respond on key down instead of key up. This helps make your abilities feel more responsive."] = "Горячие клавиши срабатывают при нажатии, а не при отпускании. Это помогает сделать способности более отзывчивыми."
L["No other profiles to sync to"] = "Нет других профилей для синхронизации"
L["No Profile Level Customizations"] = "Без настроек на уровне профиля"
L["Optimizes your graphics settings for maximum FPS and visual clarity."] = "Оптимизирует ваши графические настройки для максимального FPS и четкости изображения."
L["Patreon"] = "Patreon"
L["PayPal"] = "PayPal"
L["Pet Move"] = "Перемещение питомца"
L["Prevents Blizzard from dimming Swiftmend on action bars and CDM based on Efflorescence state."] = "Предотвращает затемнение Быстрого восстановления на панелях команд при наличии эффекта Периода цветения."
L["Reset to default"] = "Сбросить по умолчанию"
L["Set UI Scale to 0.5333"] = "Установить масштаб 0.5333"
L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "Задает цвет акцента для всех элементов EllesmereUI (вкладок, свечений, подсветок, границ). По умолчанию: цвет темы."
L["Sets the scale of the entire game UI. Lower values make everything smaller, higher values make everything larger."] = "Задает масштаб всего игрового интерфейса. Меньшие значения делают элементы меньше, большие — крупнее."
L["Sets the UI scale to the exact pixel-perfect value used by other addons. EllesmereUI does not require this to be pixel perfect."] = "Устанавливает масштаб интерфейса на точное значение pixel-perfect. EllesmereUI не требует обязательной пиксельной точности."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "Язык отображения панели настроек EllesmereUI. Автоматически следует за языком вашего клиента игры. Непереведенный текст отображается на английском."
L["the Randomly trigger"] = "случайный триггер"
L["This bar will only show if you have an enemy targeted"] = "Эта панель будет отображаться только при наличии враждебной цели"
L["This element doesn't support both Height and Width matching"] = "Этот элемент не поддерживает сопоставление по высоте и ширине одновременно"
L["This feature requires Snap Elements to be enabled"] = "Эта функция требует включенной привязки элементов"
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Это окно очереди заклинаний (Spell Queue Window), оно гарантирует, что вы не поставите в очередь слишком много заклинаний одновременно, из-за чего игра может казаться лагающей. Рекомендуется установить значение не менее 200 + ваш локальный пинг. Если вы не уверены, оставьте значение 400."
L["This option is only available for the Custom Color Theme"] = "Эта опция доступна только для пользовательской цветовой темы"
L["Toggle EllesmereUI's optional buttons: the Escape menu buttons and the minimap button."] = "Переключает отображение дополнительных кнопок EllesmereUI: кнопок в меню ESC и кнопки на миникарте."
L["Twitch"] = "Twitch"
L["WARNING: This feature requires you to re-log or restart WoW to take effect."] = "ВНИМАНИЕ: Для вступления этой функции в силу требуется перезапуск WoW или переподключение."
L["Your current spec has an assigned profile so you cannot switch to another. Please unassign to switch."] = "У вашей текущей специализации уже назначен профиль, поэтому переключиться нельзя. Сначала снимите назначение."
L["Are you sure you want to reset ALL EUI addon settings to their defaults? This will reload your UI."] = "Вы уверены, что хотите сбросить ВСЕ настройки аддонов EUI к значениям по умолчанию? Это перезагрузит интерфейс."
L["Better Character Panel conflicts with the EllesmereUI's Character Sheet. Disable either Better Character Panel or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Better Character Panel конфликтует с панелью персонажа EllesmereUI. Отключите либо Better Character Panel, либо скин панели персонажа в настройках Blizzard UI Enhanced."
L["Blizzard's Edit Mode snapping may not work correctly until you reload your UI."] = "Привязка в режиме редактирования Blizzard может работать некорректно до перезагрузки интерфейса."
L["Changing cursor anchor requires a UI reload to take effect."] = "Изменение привязки курсора требует перезагрузки интерфейса."
L["Chonky Character Sheet conflicts with the EllesmereUI's Character Sheet. Disable either Chonky or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Chonky Character Sheet конфликтует с панелью персонажа EllesmereUI. Отключите либо Chonky, либо скин панели персонажа в настройках Blizzard UI Enhanced."
L["Deja Character Stats conflicts with the EllesmereUI's Character Sheet. Disable either Deja or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Deja Character Stats конфликтует с панелью персонажа EllesmereUI. Отключите либо Deja, либо скин панели персонажа в настройках Blizzard UI Enhanced."
