L["Blizzard's buff bar art, or the classic cast bar frame, with every EllesmereUI tracked bar feature."] = "Оформление полосы баффов Blizzard или классическая рамка полосы заклинаний со всеми функциями отслеживаемых полос EllesmereUI."
L["Blizzard's cast bar art, or the classic cast bar frame, with every EllesmereUI cast bar feature."] = "Оформление полосы заклинаний Blizzard или классическая рамка полосы заклинаний со всеми функциями полосы заклинаний EllesmereUI."
L["Blizzard's frame art, portraits and bar shapes, or the classic frames, with every EllesmereUI frame feature."] = "Оформление рамок, портреты и формы полос Blizzard или классические рамки со всеми функциями рамок EllesmereUI."
L["Blizzard's health and cast bar art, or the classic flat plates, with every EllesmereUI nameplate feature."] = "Оформление полос здоровья и заклинаний Blizzard или классические плоские таблички со всеми функциями индикаторов здоровья EllesmereUI."
L["Blizzard's meter window and bar art, or a window in the classic chat tabs' border, with every EllesmereUI meter feature."] = "Окно и полосы измерителя Blizzard или окно в рамке классических вкладок чата со всеми функциями измерителя EllesmereUI."
L["Blizzard's meter window and bar art, or a window in the classic chat tabs' border, with every EllesmereUI threat meter feature."] = "Окно и полосы измерителя Blizzard или окно в рамке классических вкладок чата со всеми функциями измерителя угрозы EllesmereUI."
L["Blizzard's own character sheet as the game draws it; WoW Forever keeps the item text beside the slots, and the stat colors stay with the EllesmereUI look."] = "Собственное окно персонажа Blizzard в том виде, как его рисует игра; WoW Forever оставляет текст предметов рядом с ячейками, а цвета характеристик — в стиле EllesmereUI."
L["Blizzard's own character sheet with the EllesmereUI stats, slot text and socket panel added; the Calc tab stays with the EllesmereUI look."] = "Собственное окно персонажа Blizzard с добавленными характеристиками, текстом ячеек и панелью гнёзд EllesmereUI; вкладка Calc остаётся в стиле EllesmereUI."
L["Blizzard's own chat window, tabs and input box, or the same window with the classic tab art, with every EllesmereUI chat feature."] = "Собственное окно чата, вкладки и поле ввода Blizzard или то же окно с классическими вкладками со всеми функциями чата EllesmereUI."
L["Blizzard's own frame and button art, with EllesmereUI's features."] = "Собственное оформление рамок и кнопок Blizzard с функциями EllesmereUI."
L["Blizzard's own friends window and cards, with the EllesmereUI class icons, class-coloured names and region icons added. Both stock styles look the same here."] = "Собственное окно друзей и карточки Blizzard с добавленными иконками классов, именами в цвете класса и иконками регионов EllesmereUI. Оба стандартных стиля здесь выглядят одинаково."
L["Blizzard's own tracker, with every EllesmereUI tracker feature. Both stock styles look the same here."] = "Собственный трекер Blizzard со всеми функциями трекера EllesmereUI. Оба стандартных стиля здесь выглядят одинаково."
L["Blizzard's raid frame edge and highlights, or the classic ones, with every EllesmereUI raid frame feature."] = "Края и подсветка рейдовых рамок Blizzard или классические со всеми функциями рейдовых рамок EllesmereUI."
L["Blizzard's round minimap and header, or the classic ring, with every EllesmereUI minimap feature."] = "Круглая миникарта и заголовок Blizzard или классическое кольцо со всеми функциями миникарты EllesmereUI."
L["Blizzard's rounded button art, or the classic square slots, with every EllesmereUI bar feature."] = "Скруглённые кнопки Blizzard или классические квадратные ячейки со всеми функциями панелей EllesmereUI."
L["Blizzard's rounded cooldown icons, or the classic square slots, with every EllesmereUI icon feature."] = "Скруглённые иконки восстановления Blizzard или классические квадратные ячейки со всеми функциями иконок EllesmereUI."
L["Blizzard's windows now match the EllesmereUI theme with a WoW 2.0 Dark Theme, from the Dungeon Journal to the Auction House and beyond."] = "Окна Blizzard теперь соответствуют теме EllesmereUI с тёмной темой WoW 2.0 — от путеводителя по подземельям до аукциона и не только."
