L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "Окрашивает полосу здоровья по остатку здоровья вместо сплошного цвета. Классический: от зеленого при полном здоровье через желтый к красному при нуле. Свои цвета смешивают три образца в этой строке — полное (100%), половина (50%) и пусто (0%). Класс/реакция показывает цвет класса при полном здоровье, переходя в цвета 50% и 0% по мере получения урона. Выкл. оставляет сплошные образцы цвета заливки; в любом случае градиент ниже применяется, начиная с выбранного здесь цвета."
L["Colors allied player bars using their class. Group/raid members are identified automatically; other allies are learned from target, mouseover or focus."] = "Окрашивает полосы союзных игроков по классу. Члены группы/рейда определяются автоматически; остальные союзники узнаются по цели, наведению или фокусу."
L["Colors an attackable unit's level by difficulty, as the default UI does."] = "Окрашивает уровень атакуемого юнита по сложности, как в стандартном UI."
L["Colors are shared globally from the \"%1$s\" profile.\nSwitch to it (or set Pull Colors From to this profile) to edit."] = "Цвета общие для всех из профиля \"%1$s\".\nПереключитесь на него (или укажите этот профиль в «Брать цвета из»), чтобы изменить."
L["Colors group and raid member names inside Say, Yell, Party and Raid messages."] = "Окрашивает имена членов группы и рейда в сообщениях Сказать, Крик, Группа и Рейд."
L["Colors level text by difficulty, from grey (trivial) through green, yellow and orange to red (5+ levels above you)."] = "Окрашивает уровень по сложности: от серого (несложно) через зеленый, желтый и оранжевый к красному (на 5+ уровней выше вас)."
L["Colors the bar text instead of the fill when the threshold applies."] = "Окрашивает текст полосы вместо заливки при срабатывании порога."
L["Colors the cast segment during which your interrupt will be available."] = "Окрашивает часть заклинания, в течение которой будет доступно ваше прерывание."
L["Colors the dispel type borders with your Dispel Colors instead of Blizzard's."] = "Окрашивает рамки типов рассеивания вашими цветами рассеивания вместо цветов Blizzard."
L["Colors the number by threat status. Off shows it in white."] = "Окрашивает число по уровню угрозы. Выкл. — белым."
L["Colors the number when free slots drop below this many; the swatch picks the color. Zero turns it off."] = "Окрашивает число, когда свободных ячеек меньше этого значения; образец задает цвет. Ноль — выкл."
L["Colors the strip behind the target's name by its reaction."] = "Окрашивает полосу за именем цели по ее отношению."
