L["Hide public chat ads containing whole words such as WTS, WTB, WTT, LFW, selling, buying, vendo or compro. Needs Public Chat above. Does not hide the entire Trade channel."] = "Скрывает рекламу в общих каналах, содержащую целые слова, например WTS, WTB, WTT, LFW, selling, buying, vendo или compro. Требуется включенный выше «Общий чат». Не скрывает весь канал Торговли."
L["Hide repeated messages within the repeat window. Your own messages are always shown. Requires Enable Chat."] = "Скрывает повторяющиеся сообщения в пределах окна повтора. Ваши собственные сообщения показываются всегда. Требуется «Включить чат»."
