L["Hide server death announcements such as \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\". Works in every chat window, independent of the chat types above."] = "Скрывает объявления сервера о гибели, например \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\". Работает во всех окнах чата, независимо от типов чата выше."
