L["Hides the default arena enemy frames while these are enabled."] = "Скрывает стандартные рамки противников на арене, пока эти включены."
L["Hides the Objectives header and its minimize button at the top of the tracker."] = "Скрывает заголовок «Задачи» и кнопку сворачивания вверху трекера."
L["Hides the Objectives header and its minimize button at the top of the tracker. When shown, it uses the Header Color with a divider in the Line Color."] = "Скрывает заголовок «Задачи» и кнопку сворачивания вверху трекера. Если он показан, используется цвет заголовка с разделителем цвета линии."
L["Hides the swipe and keeps the timer."] = "Скрывает затемнение, сохраняя таймер."
L["Hides the thin dividers between the messages, input field and sidebar."] = "Скрывает тонкие разделители между сообщениями, полем ввода и боковой панелью."
L["Hides this element while you are on a skyriding (glide-capable) mount, where Blizzard shows its vigor HUD."] = "Скрывает этот элемент, пока вы на летающем маунте (с планированием), когда Blizzard показывает свой индикатор бодрости."
L["Highlight Last Tick"] = "Выделять последний тик"
L["Highlight Target"] = "Выделять цель"
L["Hold a bound key, point or scroll to choose, then release to fire. Escape cancels."] = "Удерживайте назначенную клавишу, наведите или прокрутите для выбора, затем отпустите для применения. Escape отменяет."
L["Hold a key to open a menu of actions; point or scroll to choose, release to fire."] = "Удерживайте клавишу, чтобы открыть меню действий; наведите или прокрутите для выбора, отпустите для применения."
L["Hold Shift and drag row buttons to nudge them. Reset Button Positions returns them."] = "Удерживайте Shift и перетаскивайте кнопки строки для смещения. «Сбросить позиции кнопок» возвращает их."
L["Hold Shift to drag actions off locked bars."] = "Удерживайте Shift, чтобы перетаскивать действия с заблокированных панелей."
L["Hold Shift to review the Dungeon Finder role check"] = "Удерживайте Shift для просмотра проверки ролей Поиска подземелий"
L["Hold Shift to scroll to the top or bottom."] = "Удерживайте Shift для прокрутки в начало или конец."
L["Hold the key to open, release to fire. Toggle mode keeps the menu open: the Select key fires, the menu key or Escape closes."] = "Удерживайте клавишу, чтобы открыть, отпустите для применения. В режиме переключения меню остается открытым: клавиша выбора применяет, клавиша меню или Escape закрывает."
L["Holds the block at this width and clips longer text, so a plugin whose text keeps changing length never shifts the blocks beside it. Zero sizes the block to whatever the plugin currently says."] = "Фиксирует блок на этой ширине и обрезает более длинный текст, чтобы плагин с меняющейся длиной текста не сдвигал соседние блоки. Ноль подгоняет блок под текущий текст плагина."
