L["Icon Effects glows are set per filter and Frame Glow per tile on the Debuff Manager page. The template never changes them."] = "Свечения эффектов значков задаются для каждого фильтра, а свечение рамки — для каждой плитки на странице «Менеджер дебаффов». Шаблон их никогда не меняет."
