L["Icons on the member an enemy is casting at. 3.3.5 has no spell target, so the victim is the caster's target, and only enemies targeted by someone in the group (or your target, focus or mouseover) are seen."] = "Значки на участнике, в которого враг произносит заклинание. В 3.3.5 нет цели заклинания, поэтому жертвой считается цель заклинателя, и видны только враги, взятые в цель кем-то из группы (или ваша цель, фокус или объект под курсором)."
L["Icons per crowd control category: green = next is half duration, yellow = quarter, red = immune. Resets 18 seconds after the last one fades."] = "Значки для каждой категории контроля: зеленый — следующий будет вдвое короче, желтый — вчетверо, красный — иммунитет. Сбрасывается через 18 секунд после окончания последнего."
