L["Include your complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. On import this replaces the recipient's overrides entirely."] = "Включить вашу полную настройку переопределений: значения для специализаций и условий, группы, их собственные раскладки режима разблокировки и переопределения Менеджера баффов. При импорте это полностью заменяет переопределения получателя."
L["Include your Cooldown Manager spell layout (which spells sit on which bars) plus all per-spell settings for any specs you choose."] = "Включить раскладку заклинаний Менеджера перезарядки (какие заклинания на каких панелях) и все настройки заклинаний для выбранных специализаций."
