L["Pick which content these aura reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Выберите, в каком контенте появляются эти напоминания об аурах.\nЗоны отдыха (города и таверны) всегда скрыты."
L["Pick which content these consumable reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Выберите, в каком контенте появляются эти напоминания о расходниках.\nЗоны отдыха (города и таверны) всегда скрыты."
L["Pick which content these Warlock reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Выберите, в каком контенте появляются эти напоминания чернокнижника.\nЗоны отдыха (города и таверны) всегда скрыты."
L["Pick which content this section's reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Выберите, в каком контенте появляются напоминания этого раздела.\nЗоны отдыха (города и таверны) всегда скрыты."
L["Pins the bar flush against a screen edge; moving the bar in unlock mode sets this back to None."] = "Прижимает полосу к краю экрана; перемещение полосы в режиме разблокировки сбрасывает этот параметр в «Нет»."
L["Pins this block's content to the exact center of the bar; blocks before it pack left, blocks after pack right. Combined with Fill Remaining, the block also absorbs the leftover space around the center."] = "Закрепляет содержимое блока точно по центру полосы; блоки до него прижимаются влево, после — вправо. Вместе с «Заполнить остаток» блок также занимает свободное место вокруг центра."
