L["Show the equipped bag slots above the window (also toggled by the Bags header button)."] = "Показывать надетые сумки над окном (также переключается кнопкой «Сумки» в заголовке)."
L["Show the friends and flyout buttons only while the map is hovered."] = "Показывать кнопки друзей и выноса только при наведении на карту."
L["Show the keyring in the bag window."] = "Показывать связку ключей в окне сумок."
L["Show the main frames' hover highlight border on this frame. Turn off so this frame never recolors on mouseover. No effect when Highlight is off in the main frames' Hover Borders."] = "Показывать рамку подсветки при наведении основных рамок на этой рамке. Выключите, чтобы эта рамка не меняла цвет при наведении. Не действует, если подсветка выключена в «Границы при наведении» основных рамок."
L["Show the pet frame whenever you have a pet, ignoring the Player frame's visibility settings."] = "Показывать рамку питомца, когда он у вас есть, игнорируя настройки видимости рамки игрока."
