L["Showing the '%s' override's value. Edit it from that override's editing mode."] = "Показано значение переопределения «%s». Изменяйте его в режиме редактирования этого переопределения."
L["Showing this aura from any caster; click for your casts only."] = "Аура показана от любого заклинателя; щёлкните, чтобы показывать только ваши."
L["Showing this aura from your casts only; click for any caster."] = "Аура показана только от ваших заклинаний; щёлкните, чтобы показывать от любого заклинателя."
L["Shown at max level. Header shows GearScore."] = "Показывается на максимальном уровне. В заголовке — GearScore."
L["Shown on dead members being resurrected (LibResComm-1.0, bundled)."] = "Показывается на мёртвых участниках, которых воскрешают (LibResComm-1.0, в комплекте)."
L["Shows a faint white wash over each block on mouseover."] = "Показывает лёгкую белую подсветку каждого блока при наведении."
L["Shows a house or globe icon marking which latency each value is."] = "Показывает значок дома или глобуса, обозначающий тип каждой задержки."
L["Shows a rest icon while your character is resting."] = "Показывает значок отдыха, пока ваш персонаж отдыхает."
L["Shows a small white tick mark where the cast will be when your interrupt comes off cooldown."] = "Показывает маленькую белую отметку там, где будет каст, когда ваше прерывание восстановится."
L["Shows an envelope icon when you have unread mail."] = "Показывает значок конверта при непрочитанной почте."
L["Shows debuffs that match any checked Show filter (the default)."] = "Показывает дебаффы, подходящие под любой отмеченный фильтр «Показать» (по умолчанию)."
L["Shows every bar with placeholder icons while the options are open."] = "Показывает все полосы со значками-заполнителями, пока открыты настройки."
L["Shows every debuff on this frame."] = "Показывает все дебаффы на этой рамке."
L["Shows incoming heals past the health bar: yours, then other players'."] = "Показывает входящее исцеление за полосой здоровья: ваше, затем других игроков."
L["Shows large amounts using K/M suffixes (284,208g becomes 284.2Kg) instead of the full grouped number. The tooltip always shows the exact amount."] = "Показывает большие суммы с суффиксами K/M (284,208g становится 284.2Kg) вместо полного числа. В подсказке всегда точная сумма."
L["Shows only debuffs Blizzard flags as important."] = "Показывает только дебаффы, помеченные Blizzard как важные."
L["Shows only debuffs that match every checked Show filter (dispel types count as one); opposites like Non-Player Auras with Cast By You show nothing."] = "Показывает только дебаффы, подходящие под все отмеченные фильтры «Показать» (типы рассеивания считаются одним); противоположные, например «Ауры не от игроков» с «Наложено вами», не показывают ничего."
L["Shows only the debuffs you apply that Blizzard also flags as important."] = "Показывает только ваши дебаффы, которые Blizzard также помечает как важные."
L["Shows only the debuffs you apply."] = "Показывает только ваши дебаффы."
L["Shows only this frame's Tracked Auras; add them with Edit Tracked Auras at the top of this menu."] = "Показывает только отслеживаемые ауры этой рамки; добавьте их через «Изменить отслеживаемые ауры» вверху этого меню."
L["Shows silver and copper, not just gold."] = "Показывает серебро и медь, а не только золото."
L["Shows the audio icon next to the volume bar."] = "Показывает значок звука рядом с полосой громкости."
L["Shows the bag icon next to the slot count."] = "Показывает значок сумки рядом с числом ячеек."
L["Shows the coin icon next to the amount."] = "Показывает значок монеты рядом с суммой."
L["Shows the combat status text only while your character is in combat."] = "Показывает текст статуса боя только пока ваш персонаж в бою."
L["Shows the cost of the spell being cast on the power bar."] = "Показывает стоимость применяемого заклинания на полосе ресурса."
L["Shows the currency icon next to the amount."] = "Показывает значок валюты рядом с суммой."
L["Shows the currency's description text in the tooltip. Turn off for a compact tooltip with just the name and the amount."] = "Показывает описание валюты в подсказке. Выключите для компактной подсказки только с названием и количеством."
L["Shows the debuffs you apply plus important debuffs from anyone."] = "Показывает ваши дебаффы и важные дебаффы от всех."
L["Shows the frame while this unit is below full health; while enabled, a frame hidden by its visibility setting can still be clicked."] = "Показывает рамку, пока здоровье юнита неполное; когда включено, рамку, скрытую настройкой видимости, всё равно можно щёлкнуть."
L["Shows the health text elements placed in Core Text Positions."] = "Показывает элементы текста здоровья, размещённые в «Основных позициях текста»."
L["Shows the icon next to the durability readout."] = "Показывает значок рядом с показателем прочности."
L["Shows the last lines of each chat window again after a reload or relog."] = "Снова показывает последние строки каждого окна чата после перезагрузки или перезахода."
L["Shows the map pin next to the zone name."] = "Показывает метку на карте рядом с названием зоны."
L["Shows the marker icon next to the coordinates."] = "Показывает значок маркера рядом с координатами."
L["Shows the most important boss debuff (ICC, Ruby Sanctum, ToC, Ulduar, Naxxramas) as a large icon in the middle of the frame."] = "Показывает самый важный дебафф босса (ЦЛК, Рубиновое святилище, ИК, Ульдуар, Наксрамас) крупным значком в центре рамки."
L["Shows the network latency zone at the end of casts or channels, including queued spells."] = "Показывает зону сетевой задержки в конце применения или потоковых заклинаний, включая заклинания в очереди."
L["Shows the online friend and guild counters."] = "Показывает счётчики друзей и гильдии в сети."
L["Shows the overlay only for debuffs you can currently dispel."] = "Показывает наложение только для дебаффов, которые вы сейчас можете рассеять."
L["Shows the plugin's own icon next to its text."] = "Показывает собственный значок плагина рядом с его текстом."
L["Shows the plugin's text. Off leaves an icon-only block that still carries the plugin's tooltip and clicks."] = "Показывает текст плагина. Если выключено, остаётся блок только со значком, сохраняющий подсказку и щелчки плагина."
L["Shows the profession icons next to the text."] = "Показывает значки профессий рядом с текстом."
L["Shows the spec icon next to the text."] = "Показывает значок специализации рядом с текстом."
L["Shows the spell icon over the portrait while casting and lets the bar use the full width."] = "Показывает значок заклинания поверх портрета во время применения и позволяет полосе занимать всю ширину."
L["Shows the stock rune or combo point frame here instead of the pips."] = "Показывает здесь стандартную рамку рун или приемов в серии вместо делений."
L["Shows the unit's level in the frame's level circle, as the default UI does."] = "Показывает уровень юнита в круге уровня рамки, как в стандартном интерфейсе."
L["Shows the zone and the subzone together instead of the subzone alone."] = "Показывает зону и подзону вместе, а не только подзону."
L["Shows your arena opponents. Left click targets, right click sets focus."] = "Показывает ваших противников на арене. ЛКМ — выбор цели, ПКМ — фокус."
L["Shows your free bag slots."] = "Показывает свободные ячейки сумок."
L["Shows your hunter pet's happiness beside the pet frame."] = "Показывает настроение питомца охотника рядом с рамкой питомца."
L["Shows your interrupt while your focus is casting."] = "Показывает ваше прерывание, пока ваш фокус применяет заклинание."
L["Shows your interrupt while your focus or target is casting."] = "Показывает ваше прерывание, пока ваш фокус или цель применяет заклинание."
L["Shows your threat percentage on the target and focus frames while you are in combat with that unit."] = "Показывает ваш процент угрозы на рамках цели и фокуса, пока вы в бою с этим юнитом."
