L["The Combat Indicator is not available for the Focus frame."] = "Индикатор боя недоступен для рамки фокуса."
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "Менеджер перезарядки умеет гораздо больше, чем показывать перезарядки: у него есть настройки для каждого заклинания, свечение панелей, полосы отслеживания и многое другое! Посмотрите советы, как извлечь из него максимум."
L["the EllesmereUI theme"] = "тема EllesmereUI"
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "Полная противоположность «Полета на драконе (в воздухе)»: все, что не является полетом на маунте или в облике, способном к планированию, включая нахождение на земле."
L["The fallback must differ from\nthe main anchor target"] = "Запасная привязка должна отличаться\nот основной цели привязки"
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "Однотонный цвет заливки полос в темном режиме (рамки юнитов, рамки рейда, полосы ресурсов)."
L["the Frame Source to be EllesmereUI"] = "Источник рамки — EllesmereUI"
L["The gem could not be socketed."] = "Не удалось вставить самоцвет."
L["The glow line is not shown on a vertical fill or with the From Left Edge placement"] = "Линия свечения не показывается при вертикальном заполнении или при размещении «От левого края»"
L["The glow line is not shown on a vertical fill or with the From Right Edge placement"] = "Линия свечения не показывается при вертикальном заполнении или при размещении «От правого края»"
L["The glow line is not shown with Absorb Style None"] = "Линия свечения не показывается при стиле поглощения «Нет»"
L["The Lich King"] = "Король-лич"
L["the Modern background style"] = "современный стиль фона"
L["The native social window with class icons, class-coloured names, faction banners and invite auto-accept; friend actions and every social tab stay native."] = "Стандартное окно контактов с иконками классов, именами в цвете класса, баннерами фракций и автопринятием приглашений; действия с друзьями и все вкладки контактов остаются стандартными."
L["The original frames, rings and slots where the game has them, with EllesmereUI's features."] = "Оригинальные рамки, кольца и ячейки, где они есть в игре, с функциями EllesmereUI."
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "Группа переопределения '%s' уже задает пользовательский режим разблокировки для вашей текущей специализации. Настройте его там или удалите эту специализацию из группы."
L["The pasted string could not be read completely. Please paste it again."] = "Вставленную строку не удалось прочитать полностью. Вставьте ее еще раз."
L["The personal resource display's bar frame, or the classic cast bar frame, on the health, power and class resource bars, with every EllesmereUI bar feature."] = "Рамка полосы личного дисплея ресурсов или классическая рамка полосы заклинаний на полосах здоровья, ресурса и ресурса класса со всеми функциями полос EllesmereUI."
L["The Pixel Glow settings this bar's per-icon glows use. The template never changes them."] = "Настройки пиксельного свечения для свечения иконок этой панели. Шаблон никогда их не меняет."
L["The scriptProfile CVar is enabled."] = "Включена CVar scriptProfile."
L["The socketed gem will be destroyed. Continue?"] = "Вставленный самоцвет будет уничтожен. Продолжить?"
L["The taintLog and scriptProfile CVars are enabled."] = "Включены CVar taintLog и scriptProfile."
L["The taintLog CVar is enabled."] = "Включена CVar taintLog."
L["The tracker always hides in arenas"] = "Трекер всегда скрыт на аренах"
L["These are the same settings found on each module's own pages, not separate ones."] = "Это те же настройки, что и на страницах каждого модуля, а не отдельные."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "У этих специализаций есть значения переопределения, недоступные ни одному режиму редактирования групп (остались после изменения состава). Они по-прежнему действуют. Удалите одно, чтобы вернуть специализации общие значения по умолчанию."
L["Thickness in pixels. -1 follows each debuff indicator's Border setting, 0 hides the dispel color border."] = "Толщина в пикселях. -1 следует настройке рамки каждого индикатора дебаффа, 0 скрывает рамку цвета рассеивания."
L["This bar sizes its blocks itself, so the width is not this block's to choose."] = "Эта панель сама задает размер блоков, поэтому ширину этого блока выбрать нельзя."
L["This block is already the 'Fill Remaining Space' block. Check another block to move the role."] = "Этот блок уже является блоком «Заполнить оставшееся место». Отметьте другой блок, чтобы передать ему эту роль."
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "Это не меняет, какие заклинания пользователь отслеживает в CDM Blizzard.\nРекомендуется также поделиться раскладкой CDM Blizzard для каждой выбранной здесь специализации."
L["This cannot be undone. Consider exporting this profile as a backup first."] = "Это действие нельзя отменить. Сначала стоит экспортировать профиль как резервную копию."
L["This cannot be undone. Export your own profile as a backup first."] = "Это действие нельзя отменить. Сначала экспортируйте свой профиль как резервную копию."
L["This condition is coming in a future update."] = "Это условие появится в будущем обновлении."
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "Это условие сейчас не активно. Сначала выполните одно из его условий (например, войдите в подземелье), чтобы настроить раскладку в реальном контексте."
L["This control recently changed direction: it now copies FROM the frame you choose. Confirming will copy all shared settings FROM %1$s TO %2$s."] = "Этот элемент недавно поменял направление: теперь он копирует С выбранной рамки. Подтверждение скопирует все общие настройки С %1$s НА %2$s."
L["This element cannot use group-based visibility."] = "Этот элемент не может использовать видимость по группам."
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "Этот элемент показывается, как только совпадает ОДНО условие «Показать». «Скрыть» работает одинаково в обоих режимах: отмеченное «Скрыть» всегда скрывает, в любой строке."
L["This element will only show while you are inside a house or plot"] = "Этот элемент будет показываться только внутри дома или на участке"
L["This element will only show while you are mounted"] = "Этот элемент будет показываться только верхом"
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Этот экспорт включает межпрофильные настройки, которые перезапишут настройки импортирующего, включая Удобства, Hovercast и другое, чем обычно не делятся в стандартных профилях. ЭТО НЕ РЕКОМЕНДУЕТСЯ для публичного распространения профилей."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "Эта функция оптимизирует графические настройки игры для лучшего сочетания высокого FPS и четкости изображения.\n\nВы можете отменить все изменения в любой момент, нажав \"Восстановить мои настройки\" — кнопка появится после оптимизации.\n\n\nЧто мы меняем:\n\n"
L["This frame's source changes require a UI reload to take effect."] = "Изменения источника этой рамки требуют перезагрузки UI."
L["This glow is locked on its settings page."] = "Это свечение заблокировано на странице своих настроек."
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "Пользовательский менеджер баффов этой группы можно активировать или редактировать только при игре за одну из ее специализаций."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "Пользовательский менеджер дебаффов этой группы можно активировать или редактировать только при игре за одну из ее специализаций."
L["This is a CDM Bar Layout string, not a profile string."] = "Это строка раскладки панелей CDM, а не строка профиля."
L["This is an old CDM Bar Layout string. This format is no longer supported. Use the standard profile import instead."] = "Это старая строка раскладки панелей CDM. Этот формат больше не поддерживается. Используйте обычный импорт профиля."
L["This module can't be overridden. Exit the override editing session to open it."] = "Этот модуль нельзя переопределить. Выйдите из сеанса редактирования переопределения, чтобы открыть его."
L["This module is excluded from Spec Overrides."] = "Этот модуль исключен из переопределений специализаций."
L["This option can't be used while Blizzard Class Resource Art is enabled in Resource Bars."] = "Эту опцию нельзя использовать, пока в полосах ресурсов включена графика ресурса класса Blizzard."
L["This option does not apply to the player frame."] = "Эта опция не применяется к рамке игрока."
L["This option is not available on the player frame"] = "Эта опция недоступна для рамки игрока"
L["This option only affects Raid Buffs you can cast"] = "Эта опция влияет только на рейдовые баффы, которые вы можете накладывать"
L["This option only applies to the Badge style."] = "Эта опция применяется только к стилю «Значок»."
L["This option only applies when Name > Target is selected."] = "Эта опция применяется только при выборе «Имя > Цель»."
L["This option only applies when Name > Target or Target is selected."] = "Эта опция применяется только при выборе «Имя > Цель» или «Цель»."
L["This option only applies when Target is selected."] = "Эта опция применяется только при выборе «Цель»."
L["This option only applies when the text shows a name."] = "Эта опция применяется только когда текст показывает имя."
L["This option requires a 2D Portrait or Class Art Style."] = "Эта опция требует 2D-портрета или стиля графики «Класс»."
L["This option requires a Border Size above 0"] = "Эта опция требует, чтобы размер рамки был больше 0"
L["This option requires a Border Style other than Inherit (Main Frames)."] = "Эта опция требует стиля рамки, отличного от «Наследовать (основные рамки)»."
L["This option requires a Border Style other than Solid."] = "Эта опция требует стиля рамки, отличного от «Сплошной»."
L["This option requires a border style with divider art and a Border Size above 0."] = "Эта опция требует стиля рамки с разделителями и размера рамки больше 0."
L["This option requires a Circle or Pixels Circle Shape."] = "Эта опция требует формы «Круг» или «Пиксельный круг»."
L["This option requires a Dispel Overlay, Color Custom Borders or Use Dispel Colors."] = "Эта опция требует оверлея рассеивания, цветных пользовательских рамок или цветов рассеивания."
L["This option requires a Glow Style other than None"] = "Эта опция требует стиля свечения, отличного от «Нет»"
L["This option requires a Type Icon Position other than None"] = "Эта опция требует положения иконки типа, отличного от «Нет»"
L["This option requires a visible Portrait and Show Icon."] = "Эта опция требует видимого портрета и «Показывать иконку»."
L["This option requires an attached Power Bar, a Border Size above 0 and a border style with seam art."] = "Эта опция требует прикрепленной полосы ресурса, размера рамки больше 0 и стиля рамки со швами."
L["This option requires an EllesmereUI Target or Focus frame."] = "Эта опция требует рамки цели или фокуса EllesmereUI."
L["This option requires an Outer Ring other than None."] = "Эта опция требует внешнего кольца, отличного от «Нет»."
L["This option requires Art Style to be set to Class"] = "Эта опция требует стиля графики «Класс»"
L["This option requires Blizzard Style to be disabled"] = "Эта опция требует отключения стиля Blizzard"
L["This option requires Combine Spell Name and Target to be disabled."] = "Эта опция требует отключения «Объединить название заклинания и цель»."
L["This option requires Custom Border Style, Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "Эта опция требует пользовательского стиля рамки, «Показывать иконку» и «Сделать иконку частью полосы» со стилем EllesmereUI."
L["This option requires Dispel Type Borders to be enabled."] = "Эта опция требует включения рамок по типу рассеивания."
L["This option requires Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "Эта опция требует «Показывать иконку» и «Сделать иконку частью полосы» со стилем EllesmereUI."
L["This option requires Show Icon and the EllesmereUI style."] = "Эта опция требует «Показывать иконку» и стиля EllesmereUI."
L["This option requires Show Icon beside the cast bar and the EllesmereUI style."] = "Эта опция требует иконки рядом с полосой заклинаний и стиля EllesmereUI."
L["This option requires Show Level."] = "Эта опция требует «Показывать уровень»."
L["This option requires Solid or a border style with divider art, and a Border Size above 0."] = "Эта опция требует стиля «Сплошной» или стиля рамки с разделителями и размера рамки больше 0."
L["This option requires the Class Art Style."] = "Эта опция требует стиля графики «Класс»."
L["This option requires the Class Colored Shape Border and Dark Mode."] = "Эта опция требует рамки формы по цвету класса и темного режима."
L["This option requires the WoW Forever style."] = "Эта опция требует стиля WoW Forever."
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "Это перезапишет текущие настройки рамки. Положение, видимость и состояние включения рамки не изменятся."
L["This page is excluded from overrides."] = "Эта страница исключена из переопределений."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "Это навсегда перезапишет настройки профиля переопределением '%s': его сохраненные настройки и пользовательские раскладки режима разблокировки и менеджера баффов (если есть) станут базой профиля для всех специализаций. ВСЕ группы переопределений специализаций этого профиля будут удалены, и UI перезагрузится. Условные переопределения не затрагиваются."
L["This profile string does not carry any global settings."] = "Эта строка профиля не содержит глобальных настроек."
L["This profile string does not carry any override data."] = "Эта строка профиля не содержит данных переопределений."
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Эта строка профиля не содержит настроек оформления окон и подсказок."
L["This profile was created before the beta wipe and is no longer compatible. Please create a new export."] = "Этот профиль создан до сброса бета-версии и больше не совместим. Создайте новый экспорт."
L["This profile was created with a newer version of EllesmereUI. Please update your addon."] = "Этот профиль создан в более новой версии EllesmereUI. Обновите аддон."
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Этот профиль создан при масштабе UI %1$d%%; у вас %2$d%%. Изменить масштаб UI под импортированный профиль? Все профили будут отображаться в этом масштабе, так как масштаб UI не задается для профиля, но его можно в любой момент вернуть к исходному значению."
L["This setting already has an override for %s"] = "Для этой настройки уже есть переопределение для %s"
L["This setting can't be overridden."] = "Эту настройку нельзя переопределить."
L["This Setting Has Overrides"] = "У настройки есть переопределения"
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "Пользовательский режим разблокировки этой специализации принадлежит '%s'. Настройте его там или удалите специализацию из группы."
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "Это строка ПОЛНОГО ЭКСПОРТА УЧЕТНОЙ ЗАПИСИ. Она заменит ваши общие настройки учетной записи настройками отправителя, включая Удобства, привязки HoverCast, настройки заклинаний менеджера перезарядки, привязки фиксаторов, масштаб UI и клавиши профилей -- а не только профиль. Остальные профили сохранятся, но профиль с тем же именем будет заменен."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "Этот юнит использует стандартную рамку Blizzard -- настроек EllesmereUI здесь нет."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "Рамка этого юнита скрыта -- настроек EllesmereUI здесь нет."
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "Будет создан полностью отдельный менеджер баффов для этой условной группы. Изменения основного менеджера баффов больше не будут на нее влиять."
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "Будет создан полностью отдельный менеджер баффов для этой группы переопределения. Изменения основного менеджера баффов больше не будут влиять на эти специализации."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Будет создан полностью отдельный менеджер дебаффов для этой условной группы. Текущие настройки менеджера дебаффов будут скопированы как отправная точка, а изменения основного менеджера дебаффов больше не будут на нее влиять."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Будет создан полностью отдельный менеджер дебаффов для этой группы переопределения. Текущие настройки менеджера дебаффов будут скопированы как отправная точка, а изменения основного менеджера дебаффов больше не будут влиять на эти специализации."
L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "Будет создан полностью отдельный режим разблокировки для этой условной группы. Изменения основного режима разблокировки больше не будут на нее влиять."
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "Будет создан полностью отдельный режим разблокировки для этой группы переопределения. Изменения основного режима разблокировки больше не будут влиять на эти специализации."
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Это заменит ВАШИ настройки Blizz UI Enhanced (вкладки «Оформление окон» и «Подсказки, меню и всплывающие окна») настройками отправителя во ВСЕХ ваших профилях. Текущие настройки этих двух вкладок восстановить будет нельзя."
