L["When on, flask/food/weapon/poison reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Если включено, напоминания о настоях/еде/оружии/ядах показываются (приглушенно), даже если в сумках нет подходящего предмета, — как подсказка пополнить запас.\nЕсли выключено, они полностью скрыты, когда у вас нет предмета."
L["When unlocked, hold Shift and drag the minimap. Position is also available in Unlock Mode."] = "Когда разблокировано, зажмите Shift и перетащите миникарту. Положение также доступно в режиме разблокировки."
L["Where the block's content sits inside its slot."] = "Где содержимое блока располагается в его ячейке."
