L["Where to Show"] = "Где показывать"
L["Which audio channel the block's volume bar adjusts."] = "Какой аудиоканал регулирует полоса громкости блока."
L["Which latency to show: home, world, or both side by side."] = "Какую задержку показывать: домашнюю, мировую или обе рядом."
L["Which micro menu buttons this block shows."] = "Какие кнопки микроменю показывает блок."
L["Which part of the row stays in place as reminders appear and disappear."] = "Какая часть строки остается на месте при появлении и исчезновении напоминаний."
L["Which sections the gold tooltip shows."] = "Какие разделы показывает подсказка золота."
