L["Which view the bags open to by default."] = "Какой вид открывают сумки по умолчанию."
L["While Group by Category is on, drop the trailing block of empty slots so the view only shows items."] = "Пока включена группировка по категориям, убирать последний блок пустых ячеек, чтобы показывались только предметы."
L["While on a glide-capable mount, ground included, where Blizzard shows its vigor HUD. Skyriding (Airborne) additionally requires you to be flying."] = "Верхом на маунте, способном к планированию, включая землю, где Blizzard показывает индикатор бодрости. «Полет на драконе (в воздухе)» дополнительно требует, чтобы вы летели."
L["While Party Mode is active. Party Mode can start in combat (Bloodlust); secure elements such as action bars then keep their current visibility until combat ends."] = "Пока активен режим вечеринки. Режим вечеринки может начаться в бою (Жажда крови); защищенные элементы, такие как панели команд, сохраняют текущую видимость до конца боя."
