L["You changed the default value of a setting that has overrides. Overrides keep their own values, so this change will not reach the specs or conditions they cover. To change it for an override, pick that override from the class glyph beside the module search bar and edit it there."] = "Вы изменили значение по умолчанию для настройки, у которой есть переопределения. Переопределения хранят свои значения, поэтому это изменение не затронет охваченные ими специализации и условия. Чтобы изменить его для переопределения, выберите его через значок класса рядом с поиском модулей и измените там."
