L["Your current spec has its own custom unlock mode, so conditional unlock modes never apply to it. Swap to a spec without one to customize this."] = "У вашей текущей специализации свой режим разблокировки, поэтому условные режимы разблокировки к ней не применяются. Переключитесь на специализацию без него, чтобы настроить это."
